spec.expr:
max(
  sum by (client_id, topic) (
    max by (client_id, topic, partition) (
      kafka_consumer_fetch_manager_records_lag{job="parquet-writer",topic="multi-version-netflow"}
    )
  )
  / on (client_id, topic)
  clamp_min(
    max by (client_id, topic) (
      rate(
        kafka_consumer_fetch_manager_records_consumed_total{job="parquet-writer",topic="multi-version-netflow"}[15m]
      )
    ),
    1
  )
)

max by (partition) (
  max by (partition, client_id, topic) (
    kafka_consumer_fetch_manager_records_lag{job="parquet-writer",topic="multi-version-netflow"}
  )
  / on (client_id, topic) group_left
  clamp_min(
    max by (client_id, topic) (
      rate(
        kafka_consumer_fetch_manager_records_consumed_total{job="parquet-writer",topic="multi-version-netflow"}[15m]
      )
    ),
    1
  )
)

sum by (exported_instance) (
  rate(
    ingester_poll_records_sum{
      job="parquet-writer"
    }[1m]
  )
)
/
sum by (exported_instance) (
  rate(
    ingester_poll_records_count{
      job="parquet-writer"
    }[1m]
  )
)
